const char *const sylar_reconstruction_glsl[SYLAR_RECONSTRUCTION_PARTS]={
"#version 300 es\nprecision highp float;precision highp int;\nuniform sampler2D image;uniform sampler2D native_image;out vec4 color;\nbool opaque_ok=true;\nvec3 tx(vec2 pos){ivec2 size=textureSize(native_image,0);vec4 p=texelFetch(native_image,clamp(ivec2(pos),ivec2(0),size-1),0);opaque_ok=opaque_ok && p.a>.99;return p.rgb;}\nvec4 read_at(ivec2 pos){return texelFetch(image,clamp(pos,ivec2(0),textureSize(image,0)-1),0);}\nvec4 epx_boundary(){ivec2 dst=ivec2(gl_FragCoord.xy),p=dst/2;vec4 e=read_at(p),b=read_at(p+ivec2(0,-1)),d=read_at(p+ivec2(-1,0)),f=read_at(p+ivec2(1,0)),h=read_at(p+ivec2(0,1));vec4 result=e;if(!all(equal(b,h)) && !all(equal(d,f))){bool left=(dst.x&1)==0,top=(dst.y&1)==0;if(left && top && all(equal(d,b)))result=d;else if(!left && top && all(equal(b,f)))result=f;else if(left && !top && all(equal(d,h)))result=d;else if(!left && !top && all(equal(h,f)))result=f;}return result;}\nfloat df(vec3 a, vec3 b) {\n  vec3 d = abs(a - b);\n  return dot(d, vec3(0.299, 0.587, 0.114)) * 2.0 +\n         abs((a.r - b.r) - (a.b - b.b)) * 0.5;\n}\nbool eq(vec3 a, vec3 b) { return df(a, b) < 0.004; }\nvec3 reconstruct_decode(vec3 c, vec3 n, vec3 s, vec3 w, vec3 e,\n            vec3 nw, vec3 ne, vec3 sw, vec3 se, int mode) {\n  if (mode < 1) return c;\n  if (eq(c, nw) && eq(c, ne) && eq(c, sw) && eq(c, se) &&\n      eq(n, s) && eq(n, e) && eq(n, w) && !eq(c, n))\n    return mix(c, n, 0.5);\n  if (eq(c, n) && eq(c, s) && eq(e, ne) && eq(e, se) &&\n      eq(w, nw) && eq(w, sw) && eq(e, w) && !eq(c, e))\n    return mix(c, e, 0.5);\n  if (eq(c, e) && eq(c, w) && eq(n, ne) && eq(n, nw) &&\n      eq(s, se) && eq(s, sw) && eq(n, s) && !eq(c, n))\n    return mix(c, n, 0.5);\n  return c;\n}\nvec4 reconstruct_color(){\n vec2 source_size=vec2(textureSize(native_image,0)),output_size=source_size*2.,uv=gl_FragCoord.xy/output_size;\n const int mode=3;const float strength=.85,softness=.20,shading=.65;\n  vec2 pos = uv * source_size;\n  vec2 t = floor(pos);\n  vec2 fp = pos - t;\n  vec2 dir = vec2(fp.x < 0.5 ? -1.0 : 1.0, fp.y < 0.5 ? -1.0 : 1.0);\n  vec2 f = abs(fp - 0.5) + 0.5;\n  vec2 scale = max(output_size / source_size, vec2(1.0));\n  /* softness widens every transition from one output pixel to three. */\n  float band = 1.0 + 2.0 * softness;\n  float aa = min(scale.x, scale.y) / band;\n  vec2 dx = vec2(dir.x, 0.0);\n  vec2 dy = vec2(0.0, dir.y);\n  vec3 A1 = tx(t - dx - dy - dy), B1 = tx(t - dy - dy), C1 = tx(t + dx - dy - dy);\n  vec3 A0 = tx(t - dx - dx - dy), A = tx(t - dx - dy), B = tx(t - dy), C = tx(t + dx - dy), C4 = tx(t + dx + dx - dy);\n  vec3 D0 = tx(t - dx - dx), D = tx(t - dx), E = tx(t), F = tx(t + dx), F4 = tx(t + dx + dx);\n  vec3 G0 = tx(t - dx - dx + dy), G = tx(t - dx + dy), H = tx(t + dy), I = tx(t + dx + dy), I4 = tx(t + dx + dx + dy);\n",
"  vec3 G5 = tx(t - dx + dy + dy), H5 = tx(t + dy + dy), I5 = tx(t + dx + dy + dy);\n  if(!opaque_ok)return vec4(0);\n  vec3 e = reconstruct_decode(E, B, H, D, F, A, C, G, I, mode);\n  vec3 fc = reconstruct_decode(F, C, I, E, F4, B, C4, H, I4, mode);\n  vec3 hc = reconstruct_decode(H, E, H5, G, I, D, F, G5, I5, mode);\n  vec3 ic = reconstruct_decode(I, F, I5, H, I4, E, F4, H5, I5, mode);\n  /* f runs from the texel center (0.5) to its edge (1.0); blend half\n     way to the neighbor over the last output pixel before the edge,\n     and the neighbor's fragments continue the other half. */\n  vec2 adj = 0.5 * clamp((f - (1.0 - 0.5 * band / scale)) * scale / band,\n                         0.0, 1.0);\n  vec3 base = mix(mix(e, fc, adj.x), mix(hc, ic, adj.x), adj.y);\n  /* Smooth shading: where the neighbors are close in color (a shading\n     band of the pre-rendered art, not an outline), interpolate them\n     into a gradient instead of flat steps. */\n  if (shading > 0.0) {\n    vec2 g = f - 0.5;\n    vec3 bil = mix(mix(e, fc, g.x), mix(hc, ic, g.x), g.y);\n    float sim = max(max(df(e, fc), df(e, hc)), df(e, ic));\n    float w = shading * (1.0 - smoothstep(0.03, 0.14, sim));\n    base = mix(base, bil, w);\n  }\n  if (mode < 2) { return vec4(base, 1.0); }\n  float wd1 = df(E, C) + df(E, G) + df(I, H5) + df(I, F4) + 4.0 * df(H, F);\n  float wd2 = df(H, D) + df(H, I5) + df(F, I4) + df(F, B) + 4.0 * df(E, I);\n  bool edr = wd1 < wd2 && !eq(E, H) && !eq(E, F) && !(eq(E, I) && eq(H, F));\n  if (!edr) { return vec4(base, 1.0); }\n  vec3 nc = (df(E, F) <= df(E, H)) ? fc : hc;\n  float cov = clamp((f.x + f.y - 1.5) * aa + 0.5, 0.0, 1.0);\n  if (mode >= 3) {\n    bool left = 2.0 * df(F, G) <= df(H, C) && !eq(E, G) && !eq(D, G);\n    bool up = df(F, G) >= 2.0 * df(H, C) && !eq(E, C) && !eq(B, C);\n    if (left) cov = max(cov, clamp((2.0 * f.x + f.y - 2.0) * aa * 0.75 + 0.5, 0.0, 1.0));\n    if (up) cov = max(cov, clamp((f.x + 2.0 * f.y - 2.0) * aa * 0.75 + 0.5, 0.0, 1.0));\n    if (mode >= 4) {\n      bool left3 = left && 4.0 * df(F, G) <= df(H, C) && !eq(E, G0) && !eq(D0, G0);\n      bool up3 = up && df(F, G) >= 4.0 * df(H, C) && !eq(E, C1) && !eq(B1, C1);\n      if (left3) cov = max(cov, clamp((3.0 * f.x + f.y - 2.5) * aa * 0.6 + 0.5, 0.0, 1.0));\n      if (up3) cov = max(cov, clamp((f.x + 3.0 * f.y - 2.5) * aa * 0.6 + 0.5, 0.0, 1.0));\n    }\n  }\n  return vec4(mix(base, nc, cov * strength), 1.0);\n}\n\nvec3 linear_color(vec3 c){vec3 lo=c/12.92,hi=pow((c+.055)/1.055,vec3(2.4));return mix(lo,hi,step(vec3(.04045),c));}\nvoid main(){ivec2 size=textureSize(native_image,0),center=clamp(ivec2(gl_FragCoord.xy)/2,ivec2(0),size-1);if(texelFetch(native_image,center,0).a<.99){color=epx_boundary();return;}vec4 reconstructed=reconstruct_color();color=opaque_ok?vec4(linear_color(reconstructed.rgb),1):epx_boundary();}\n"
};
